老师，不是说“若有新goroutine竞争大概率新goroutine获得”，为什么下边的代码，每次都是50个旧的go程抢到锁之后，新的go程才会抢到。而不是在50个旧的go程执行的过程中，被每隔五秒创建的100个新的go程给抢断了。希望老师帮忙解释一下，万分感谢。

func main() {

	var mux sync.Mutex
	for i := 1; i &lt;= 50; i++ {
		go func(i int) {
			mux.Lock()
			fmt.Printf(&quot;第%d个go程获取到锁！\n&quot;, i)
			time.Sleep(time.Second)
			mux.Unlock()
		}(i)
		time.Sleep(time.Millisecond)
		fmt.Printf(&quot;第%d个go程准备就位\n&quot;, i)
	}

	&#47;&#47; 睡两秒确保上述50个go程均处于阻塞状态
	time.Sleep(time.Second * 2)

	&#47;&#47; 监听go程数量
	go func() {
		for i := 0; i &lt; 1000; i++ {
			fmt.Println(&quot;此时go程的数量是:&quot;, runtime.NumGoroutine())
			time.Sleep(time.Second)
		}
	}()

	&#47;&#47; 每隔五秒创建100个新的go程，同样无法模拟新的go程会比之前50个go程优先抢到锁
	for {
		for i := 0; i &lt; 100; i++ {
			go func() {
				mux.Lock()
				fmt.Println(&quot;新go程获取到锁！&quot;)
				mux.Unlock()
			}()
		}
		time.Sleep(time.Second * 5)
	}
}

鸟窝大大你好，请教下为什么在协程内部fmt.Println后最后的结果会是正常的，因为fmt是安全的么
func main() {
	var count = 0

	var wg sync.WaitGroup

	wg.Add(10)

	for i := 0; i &lt; 10; i++ {
		go func() {
			defer wg.Done()
			for j := 0; j &lt; 10000; j++ {
			count++
				fmt.Println(count)
			}
		}()
	}

	wg.Wait()

	fmt.Println(count)
}

package main


